import { useState } from "react";
import { useForm } from "react-hook-form";
import { useNavigate } from "react-router-dom";
import userService from "../services/userService";
import { setAccessToken } from "../services/tokenStorage";

const HomePage = () => {
  const [authForm, setAuthForm] = useState(null); // uses the useState hook to manage the state of the authentication form (authForm), and the useForm hook to manage the form data.
  const { register, handleSubmit, reset } = useForm();

  const navigate = useNavigate();

  const onSubmitHandler = async (formData) => {
    try {
      let response;
      if (authForm === "login") response = await userService.logIn(formData);

      if (authForm === "signup") response = await userService.signUp(formData);

      if (response.success) {
        setAccessToken(response.access_token);
        navigate("/courses");
        reset();
      }
    } catch (error) {
      alert(error);
    }
  };

  return (
    <>
      <h1>Cerbos React Demo</h1>

      <div className="buttons">
        <span onClick={() => setAuthForm("login")}>Sign In </span>|
        <span onClick={() => setAuthForm("signup")}> Sign Up</span>
      </div>

      {authForm === "login" && (
        <form onSubmit={handleSubmit(onSubmitHandler)} className="form">
          <input type="email" placeholder="email" {...register("email")} />
          <input
            type="password"
            placeholder="password"
            {...register("password")}
          />
          <button type="submit">Login</button>
        </form>
      )}

      {authForm === "signup" && (
        <form onSubmit={handleSubmit(onSubmitHandler)} className="form">
          <input type="text" placeholder="name" {...register("name")} />
          <input type="email" placeholder="email" {...register("email")} />
          <input
            type="password"
            placeholder="password"
            {...register("password")}
          />
          <button type="submit">Signup</button>
        </form>
      )}
    </>
  );
};

export default HomePage;

import { v4 as uuidv4 } from "uuid";

const userService = {
  getAllUsers: () => {
    const localValue = localStorage.getItem("Users");
    return localValue ? JSON.parse(localValue) : [];
  },

  getUser: (property) => {
    const localValue = localStorage.getItem("Users");
    const users = localValue ? JSON.parse(localValue) : [];

    return users.find((user) => user.email === property || user.id == property);
  },

  getUserId: (token) => {
    const localValue = localStorage.getItem("Users");
    const users = localValue ? JSON.parse(localValue) : [];

    return users.find((user) => user.accessToken === token);
  },

  createUser: (user) => {
    const localValue = localStorage.getItem("Users");
    const users = localValue ? JSON.parse(localValue) : [];

    const userId = users.length + 1;
    users.push({ id: `${userId}`, ...user });

    localStorage.setItem("Users", JSON.stringify(users));
  },

  updateUser: (user) => {
    const localValue = localStorage.getItem("Users");
    const users = JSON.parse(localValue);

    const updatedUser = users.map((u) =>
      u.id === user.id ? { ...u, ...user } : u,
    );

    localStorage.setItem("Users", JSON.stringify(updatedUser));
  },

  logIn: (formData) => {
    return new Promise((resolve, reject) => {
      const { email, password } = formData;

      setTimeout(async () => {
        const user = userService.getUser(email);
        if (!user) {
          reject("Email doesn’t exist.");
          return;
        }

        if (password !== user.password) {
          reject("Enter Right Password");
          return;
        }

        const accessToken = uuidv4();

        const updatedUser = { ...user, accessToken };
        userService.updateUser(updatedUser);

        resolve({ success: true, access_token: accessToken });
      }, 500);
    });
  },

  signUp: (formData) => {
    return new Promise((resolve, reject) => {
      const { name, email, password, roles } = formData;

      setTimeout(() => {
        const user = userService.getUser(email);
        if (user) {
          reject("User Already Exists");
          return;
        }

        const accessToken = uuidv4();

        userService.createUser({ name, email, password, accessToken, roles });

        resolve({ success: true, access_token: accessToken });
      }, 500);
    });
  },
};

export default userService;

import userService from "./userService";

const courseService = {
  getAllCourses: () => {
    return new Promise((resolve) => {
      setTimeout(() => {
        const localValue = localStorage.getItem("Courses");

        resolve({
          success: true,
          data: localValue ? JSON.parse(localValue) : [],
        });
      }, 500); // Simulate delay for API call
    });
  },

  createCourse: (course) => {
    return new Promise((resolve) => {
      setTimeout(() => {
        const localValue = localStorage.getItem("Courses");
        const courses = localValue ? JSON.parse(localValue) : [];

        const author = userService.getUser(course.authorId);
        course.author = author.name;

        const courseId = courses.length + 1;

        const newCourse = { id: courseId.toString(), ...course };
        courses.push(newCourse);
        localStorage.setItem("Courses", JSON.stringify(courses));

        resolve({ success: true, data: newCourse });
      }, 500); // Simulate delay for API call
    });
  },

  updateCourse: (course) => {
    return new Promise((resolve) => {
      setTimeout(() => {
        const localValue = localStorage.getItem("Courses");
        const courses = JSON.parse(localValue);

        const updatedCourse = courses.map((c) =>
          c.id === course.id ? { ...c, ...course } : c,
        );
        localStorage.setItem("Courses", JSON.stringify(updatedCourse));

        resolve({ success: true });
      }, 500); // Simulate delay for API call
    });
  },

  deleteCourse: (id) => {
    return new Promise((resolve) => {
      setTimeout(() => {
        const localValue = localStorage.getItem("Courses");
        const courses = JSON.parse(localValue);

        const result = courses.filter((c) => c.id !== id);
        localStorage.setItem("Courses", JSON.stringify(result));

        resolve({ success: true });
      }, 500); // Simulate delay for API call
    });
  },
};

export default courseService;

import { useEffect, useState, useMemo, useCallback } from "react";
import { useCerbos } from "@cerbos/react";
import courseService from "../services/courseService";

const useCourses = () => {
  const cerbos = useCerbos();

  const [courses, setCourses] = useState([]);
  const [error, setError] = useState("");
  const [isLoading, setLoading] = useState(false);

  const fetchCourses = useCallback(async () => {
    console.log("Fetching courses...");
    setLoading(true);

    try {
      const res = await courseService.getAllCourses();

      const authorizedCourses = await Promise.all(
        res.data.map(async (course) => {
          const check = await cerbos.checkResource({
            resource: {
              kind: "course",
              id: course.id,
              attr: JSON.parse(JSON.stringify(course)),
            },
            actions: ["view", "update", "delete"],
          });

          return (
            check.isAllowed("view") && {
              ...course,
              canUpdate: check.isAllowed("update"),
              canDelete: check.isAllowed("delete"),
            }
          );
        }),
      );

      setCourses(authorizedCourses.filter(Boolean));
    } catch (error) {
      console.error(
        "Error during course retrieval or authorization check:",
        error,
      );
      setError(error.message);
    } finally {
      console.log("Course fetching completed.");
      setLoading(false);
    }
  }, [cerbos]);

  useEffect(() => {
    fetchCourses();
  }, [fetchCourses]);

  console.log("Returning courses:", courses);
  return { courses, error, isLoading, setCourses, setError, fetchCourses };
};

export default useCourses;

import CoursesPage from "./CoursesPage";
import HomePage from "./HomePage";

export { HomePage, CoursesPage };

import { useEffect } from "react";
import { useNavigate } from "react-router-dom";

import { getAccessToken, removeAccessToken } from "../services/tokenStorage";
import useCourses from "../hooks/useCourses";

const CoursesPage = () => {
  const navigate = useNavigate();

  useEffect(() => {
    if (!getAccessToken()) navigate("/");
  }, [navigate]);

  const logOut = () => {
    removeAccessToken();
    navigate("/");
  };

  const { courses, isLoading } = useCourses();

  if (isLoading) {
    return <>Loading...</>;
  }

  return (
    <>
      <button onClick={logOut} className="logout">
        Log Out
      </button>
      {courses.map((course, index) => {
        return (
          <div key={index} className="course">
            <span>{course.title}</span>
            <span>${course.price}</span>
            <span>{course.status}</span>
            <span>{course.author}</span>
            <label htmlFor="update">
              Update
              <input
                type="checkbox"
                name="update"
                id="update"
                defaultChecked={course.canUpdate}
              />
            </label>
            <label htmlFor="delete">
              Delete
              <input
                type="checkbox"
                name="delete"
                id="delete"
                defaultChecked={course.canDelete}
              />
            </label>
          </div>
        );
      })}
    </>
  );
};

export default CoursesPage;
